INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-029', TRUE, '安徽农业大学官网', NULL, '我校承办第六届土壤生物健康研讨会', '讲座培训', NULL, '2026-11-03', NULL, NULL, NULL, 0.5, 'medium', '[{"text": "我校承办第六届土壤生物健康研讨会 【 发布日期：2026-11-03 】 【 来源：资源与环境学院", "quote": "我校承办第六届土壤生物健康研讨会 【 发布日期：2026-11-03 】 【 来源：资源与环境学院"}]'::jsonb, '讲座培训：我校承办第六届土壤生物健康研讨会', '[{"text": "我校承办第六届土壤生物健康研讨会 【 发布日期：2026-11-03 】 【 来源：资源与环境学院", "quote": "我校承办第六届土壤生物健康研讨会 【 发布日期：2026-11-03 】 【 来源：资源与环境学院"}]'::jsonb, '我校承办第六届土壤生物健康研讨会 【 发布日期：2026-11-03 】 【 来源：资源与环境学院 】 【 点击数： 】 本网讯 10月25日至27日，第六届土壤生物健康研讨会在阜阳市临泉县举办。本次研讨会以“土壤生物健康与农业绿色发展”为主题，由南京农业大学资源与环境科学学院、江苏省土壤学会主办，我校资源与环境学院等单位共同承办。党委常委、副校长吴祥为出席开幕式并致辞。 吴祥为在致辞中向与会专家学者表示热烈欢迎，并简要介绍了学校历史以及近年来在农业资源与环境、生态学等学科的建设成效。他表示，土壤生物健康是保障粮食', 'http://news.ahau.edu.cn/info/1005/143377.htm', '安徽农业大学官网', 'www', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at